const SOAP='http://schemas.xmlsoap.org/soap/envelope/',TEMP='http://tempuri.org/',DATA='http://schemas.datacontract.org/2004/07/NC.DG.TMS.C.WCF.NIWS';
const escape=(value:string)=>value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
export function niwsStringResponse(method:string,value:string){return`<s:Envelope xmlns:s="${SOAP}"><s:Body><${method}Response xmlns="${TEMP}"><${method}Result>${escape(value)}</${method}Result></${method}Response></s:Body></s:Envelope>`;}
export function niwsMandateResponse(code:string,url:string|null,errors:string[]=[]){return`<s:Envelope xmlns:s="${SOAP}"><s:Body><AddMandateResponse xmlns="${TEMP}"><AddMandateResult xmlns:a="${DATA}" xmlns:i="http://www.w3.org/2001/XMLSchema-instance"><a:ErrorCode>${escape(code)}</a:ErrorCode><a:Errors xmlns:b="http://schemas.microsoft.com/2003/10/Serialization/Arrays">${errors.map(v=>`<b:string>${escape(v)}</b:string>`).join('')}</a:Errors>${url===null?'<a:MandateUrl i:nil="true"/>':`<a:MandateUrl>${escape(url)}</a:MandateUrl>`}<a:Warnings i:nil="true"/></AddMandateResult></AddMandateResponse></s:Body></s:Envelope>`;}
